import { defineComponent, PropType } from 'vue';

import { IDebugBooleanSetting, IDebugEnumSetting, IDebugNumberSetting, IDebugSettingType, IDebugSliderSetting, IDebugStringSetting, IDebugTriggerSetting } from '../../types';

export default defineComponent({
    name: 'DebugSetting',
    props: {
        setting: { type: Object as PropType<IDebugSettingType>, required: true }
    },
    data() {
        return {
            settingName: '',
            showUpdate: true,
            inputText: false,
            showCheck: false,
            inputNumber: false,
            inputRange: false,
            showSlider: false,
            showEnum: false,
            selectedEnum: ''
        };
    },
    computed: {
        // TODO: Consider a wider refactor to enable TypeScript to narrow the type automatically
        settingAsText(): IDebugStringSetting {
            return this.setting as IDebugStringSetting;
        },
        settingAsNumber(): IDebugNumberSetting {
            return this.setting as IDebugNumberSetting;
        },
        settingAsTrigger(): IDebugTriggerSetting {
            return this.setting as IDebugTriggerSetting;
        },
        settingAsCheckbox(): IDebugBooleanSetting {
            return this.setting as IDebugBooleanSetting;
        },
        settingAsSlider(): IDebugSliderSetting {
            return this.setting as IDebugSliderSetting;
        },
        settingAsEnum(): IDebugEnumSetting {
            return this.setting as IDebugEnumSetting;
        }
    },
    mounted(): void {
        this.settingName = this.setting.name;

        this.showUpdate = this.setting.type === 'trigger';
        this.showCheck = this.setting.type === 'boolean';
        this.inputText = this.setting.type === 'string';
        this.showSlider = this.setting.type === 'slider';
        this.inputNumber = this.setting.type === 'number';
        this.showEnum = this.setting.type === 'enum';
        if (this.showEnum) {
            const enumSetting = this.setting as IDebugEnumSetting;
            this.selectedEnum = enumSetting.availableValues[enumSetting.currentValue];
        }
    },
    methods: {
        onClick(): void {
            this.setting.onChange(this.setting);
            if (this.setting.type === 'slider') {
                this.$forceUpdate();
            }
        },
        updateEnumOption(option: string): void {
            this.selectedEnum = option;
            const enumSetting = this.setting as IDebugEnumSetting;
            enumSetting.currentValue = enumSetting.availableValues.indexOf(option);
            this.onClick();
        }
    }
});
